// Generate personalized email content
const userData = $('Split Users').first().json;
const matchesData = $input.first().json;

const userName = userData.name || 'Valued Customer';
const userEmail = userData.email;
const matches = matchesData.matches || [];

// Create email subject
const subject = `🎉 ${matches.length} Personal Loan Options Found for You!`;

// Generate email body
let emailBody = `
<!DOCTYPE html>
<html>
<head>
    <style>
        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
        .header { background-color: #4CAF50; color: white; padding: 20px; text-align: center; }
        .content { padding: 20px; }
        .loan-card { border: 1px solid #ddd; border-radius: 8px; padding: 15px; margin: 10px 0; background-color: #f9f9f9; }
        .lender { font-weight: bold; color: #4CAF50; font-size: 18px; }
        .rate { color: #FF6B6B; font-weight: bold; }
        .score { background-color: #E3F2FD; padding: 5px 10px; border-radius: 15px; font-size: 12px; }
        .footer { background-color: #f1f1f1; padding: 15px; text-align: center; font-size: 12px; }
    </style>
</head>
<body>
    <div class="header">
        <h1>Personal Loan Matches Found!</h1>
        <p>Hello ${userName}, we found ${matches.length} loan options tailored for you</p>
    </div>

    <div class="content">
        <h2>Your Personalized Loan Recommendations</h2>
        <p>Based on your profile, here are the loan products you're eligible for:</p>
`;

// Add loan cards
matches.slice(0, 5).forEach((match, index) => {
    const eligibilityBadge = match.eligibility_status === 'eligible' ? 
        '<span class="score" style="background-color: #C8E6C9;">✅ Highly Eligible</span>' :
        '<span class="score" style="background-color: #FFF3E0;">⚠️ Partially Eligible</span>';

    const matchScore = Math.round(match.match_score * 100);

    emailBody += `
        <div class="loan-card">
            <div class="lender">${match.lender_name}</div>
            <h3>${match.product_name}</h3>
            <p><strong>Interest Rate:</strong> <span class="rate">${match.interest_rate_min}% - ${match.interest_rate_max}%</span></p>
            <p><strong>Loan Amount:</strong> ₹${(match.loan_amount_min/100000).toFixed(1)}L - ₹${(match.loan_amount_max/100000).toFixed(1)}L</p>
            <p><strong>Match Score:</strong> ${matchScore}%</p>
            <p>${eligibilityBadge}</p>
            <p><strong>Why this matches:</strong> ${match.match_reasons.slice(0,3).join(', ')}</p>
        </div>
    `;
});

if (matches.length > 5) {
    emailBody += `<p><strong>And ${matches.length - 5} more options available!</strong></p>`;
}

emailBody += `
        <div style="background-color: #E8F5E8; padding: 15px; border-radius: 8px; margin: 20px 0;">
            <h3>💡 Next Steps:</h3>
            <ol>
                <li>Review the loan options above</li>
                <li>Compare interest rates and terms</li>
                <li>Check with the lenders directly for final approval</li>
                <li>Ensure you have all required documents ready</li>
            </ol>
        </div>

        <p><strong>Important:</strong> These are indicative matches based on your profile. Final approval depends on the lender's detailed verification process.</p>
    </div>

    <div class="footer">
        <p>This email was sent because you recently uploaded your information to our loan matching service.</p>
        <p>© 2024 Loan Eligibility Engine. All rights reserved.</p>
    </div>
</body>
</html>
`;

return [{
    json: {
        user_id: userData.user_id,
        user_name: userName,
        user_email: userEmail,
        email_subject: subject,
        email_body: emailBody,
        matched_products_count: matches.length,
        notification_type: 'loan_matches'
    }
}];

// Log notification results
const results = $input.all();
const totalNotifications = results.length;

console.log(`User Notification workflow completed. Sent ${totalNotifications} notifications.`);

return [{ 
  json: { 
    workflow: 'User Notification',
    execution_time: new Date().toISOString(),
    notifications_sent: totalNotifications,
    status: 'completed'
  } 
}];
